INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_01', 'o-level-mathematics-4024', 'Cambridge O Level Mathematics (4024)', 'O-Level Maths', '4024', 'Cambridge (CAIE)', 'O Level', 'Year 9 – 11 (Grades 9–11)', 'Struggling with O-Level Maths? Let''s make it easier.', 'Complete one-to-one online tutoring for Cambridge O Level Mathematics 4024: concepts made simple, topic-by-topic mastery, past-paper practice and proven exam strategies for both papers.', 'O Level Mathematics is our core speciality. Every lesson starts with understanding: why a method works, not just how to use it. We then practise with carefully chosen questions, apply the idea to real exam-style problems, and build the speed and accuracy needed for Paper 1 (non-calculator) and Paper 2 (calculator).

Students get a personalised plan based on their current level and target grade, regular topical worksheets, timed past papers with full mark-scheme walkthroughs, and progress reports for parents. Whether you are aiming to pass comfortably or chasing an A*, we tailor every session to you.', '["Number: fractions, percentages, standard form, bounds, ratio & proportion","Algebra: expressions, equations, inequalities, sequences, indices","Functions & graphs: linear, quadratic, cubic, reciprocal, gradients","Coordinate geometry: straight lines, midpoints, lengths, parallel & perpendicular","Geometry: angles, polygons, circle theorems, similarity & congruence","Mensuration: perimeter, area, surface area, volume, arcs & sectors","Trigonometry: SOHCAHTOA, sine & cosine rule, bearings, 3D problems","Transformations & vectors: reflection, rotation, enlargement, vector geometry","Probability: single & combined events, tree diagrams, Venn diagrams","Statistics: averages, cumulative frequency, histograms, scatter graphs"]', '["Concepts made simple, step by step","Topical & full past-paper practice","Non-calculator techniques for Paper 1","Exam strategies & time management","Mark-scheme based answer writing","Progress reports for parents"]', '[{"name":"Paper 1 — Non-calculator","duration":"2 hours","marks":"100 marks","weight":"50%"},{"name":"Paper 2 — Calculator","duration":"2 hours","marks":"100 marks","weight":"50%"}]', 'orange', 1, 1, 1, 'O Level Maths Tutor Online | Cambridge O Level Mathematics 4024', 'Expert one-to-one online O Level Maths (4024) tutoring. Concepts made simple, past-paper practice and exam strategies for Paper 1 & 2. Book a FREE demo class today.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_02', 'igcse-mathematics-0580', 'Cambridge IGCSE Mathematics (0580)', 'IGCSE Maths 0580', '0580', 'Cambridge (CAIE)', 'IGCSE', 'Year 9 – 11', 'Core or Extended: master every topic with confidence.', 'Personalised tutoring for Cambridge IGCSE Mathematics 0580, covering both Core and Extended tiers with concept building, topical practice and full past-paper preparation.', 'IGCSE 0580 rewards students who truly understand the ideas behind each topic. We work through the syllabus at the right pace for each learner, strengthen weak areas, and then sharpen exam technique using recent past papers and mark schemes.

We help students and parents decide between Core and Extended, set a realistic target grade, and track progress with regular reports.', '["Number","Algebra and graphs","Coordinate geometry","Geometry","Mensuration","Trigonometry","Transformations and vectors","Probability","Statistics"]', '["Core & Extended tiers","Calculator & non-calculator skills","Past papers with mark schemes","Target-grade planning"]', '[{"name":"Core: Paper 1 (non-calculator) + Paper 3 (calculator)","duration":"1h 30m each","marks":"80 marks each","weight":"50% each"},{"name":"Extended: Paper 2 (non-calculator) + Paper 4 (calculator)","duration":"2 hours each","marks":"100 marks each","weight":"50% each"}]', 'teal', 1, 1, 2, 'IGCSE Maths 0580 Tutor Online | Core & Extended', 'One-to-one online tutoring for Cambridge IGCSE Mathematics 0580 (Core & Extended). Concept building, past papers and exam technique. Free demo class.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_03', 'igcse-additional-mathematics-0606', 'Cambridge IGCSE Additional Mathematics (0606)', 'Add Maths 0606', '0606', 'Cambridge (CAIE)', 'IGCSE', 'Year 10 – 11', 'Bridge the gap to A Level with Additional Maths.', 'Focused support for IGCSE Additional Mathematics 0606: functions, calculus, trigonometry and more, taught clearly for strong students aiming high.', 'Additional Mathematics introduces ideas that many students meet for the first time, including calculus, logarithms and radian measure. We break each topic into clear steps, connect it to what students already know, and practise extensively with exam-style questions so that tricky problems become routine.', '["Functions","Quadratic functions","Factors of polynomials","Equations, inequalities and graphs","Simultaneous equations","Logarithmic and exponential functions","Straight-line graphs","Coordinate geometry of the circle","Circular measure","Trigonometry","Permutations and combinations","Series","Vectors in two dimensions","Calculus"]', '["Calculus made intuitive","Excellent A Level preparation","Challenging problem practice","Past papers & mark schemes"]', '[{"name":"Paper 1","duration":"2 hours","marks":"80 marks","weight":"50%"},{"name":"Paper 2","duration":"2 hours","marks":"80 marks","weight":"50%"}]', 'blue', 1, 1, 3, 'IGCSE Additional Maths 0606 Tutor Online', 'Expert online tutoring for Cambridge IGCSE Additional Mathematics 0606: calculus, functions, logarithms and trigonometry. Book a free demo.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_04', 'igcse-international-mathematics-0607', 'Cambridge IGCSE International Mathematics (0607)', 'Int''l Maths 0607', '0607', 'Cambridge (CAIE)', 'IGCSE', 'Year 9 – 11', 'Graphic-calculator maths with real-world modelling.', 'Tutoring for Cambridge IGCSE International Mathematics 0607, including graphic display calculator skills, investigation and modelling.', 'International Mathematics combines a broad syllabus with the use of a graphic display calculator and an investigation and modelling component. We teach the content clearly, build confident calculator technique, and practise the reasoning and communication skills that investigation questions reward.', '["Number","Algebra","Functions","Coordinate geometry","Geometry","Mensuration","Trigonometry","Vectors and transformations","Probability","Statistics"]', '["Graphic calculator technique","Investigation & modelling skills","Core & Extended support","Past-paper practice"]', NULL, 'violet', 0, 1, 4, 'IGCSE International Maths 0607 Tutor Online', 'One-to-one online tutoring for Cambridge IGCSE International Mathematics 0607 with graphic calculator and modelling skills. Free demo class.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_05', 'gcse-mathematics', 'GCSE Mathematics (Edexcel, AQA & OCR)', 'GCSE Maths', NULL, 'Edexcel / AQA / OCR', 'GCSE', 'Year 9 – 11', 'Foundation or Higher: aim for your best grade (9–1).', 'Online GCSE Maths tutoring for UK exam boards Edexcel, AQA and OCR, Foundation and Higher tiers, with targeted revision and past-paper practice.', 'We follow your exam board''s specification closely, identify gaps quickly, and build a revision plan around your target grade. Lessons combine clear explanations, worked examples, and timed practice so students walk into every paper prepared.', '["Number","Algebra","Ratio, proportion and rates of change","Geometry and measures","Probability","Statistics"]', '["Edexcel, AQA & OCR specifications","Foundation & Higher tiers","Grade 9–1 target planning","Topic & full-paper practice"]', '[{"name":"Paper 1 — Non-calculator","duration":"1h 30m","marks":"80 marks","weight":"33⅓%"},{"name":"Paper 2 — Calculator","duration":"1h 30m","marks":"80 marks","weight":"33⅓%"},{"name":"Paper 3 — Calculator","duration":"1h 30m","marks":"80 marks","weight":"33⅓%"}]', 'teal', 1, 1, 5, 'GCSE Maths Tutor Online | Edexcel, AQA & OCR', 'Online one-to-one GCSE Maths tutoring for Edexcel, AQA and OCR (Foundation & Higher). Personalised revision and past papers. Free demo.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_06', 'edexcel-international-gcse-mathematics', 'Edexcel International GCSE Mathematics', 'Edexcel IGCSE', '4MA1', 'Pearson Edexcel', 'International GCSE', 'Year 9 – 11', 'Clear teaching for every Edexcel International GCSE topic.', 'Tutoring for Pearson Edexcel International GCSE Mathematics (Specification A), Foundation and Higher tiers.', 'We cover the full Edexcel International GCSE specification with a strong focus on method, accuracy and presentation. Students practise with past papers and examiner-style questions to maximise marks.', '["Numbers and the number system","Equations, formulae and identities","Sequences, functions and graphs","Geometry and trigonometry","Vectors and transformation geometry","Statistics and probability"]', '["Foundation & Higher tiers","Examiner-style questions","Past papers & mark schemes","Flexible worldwide timings"]', '[{"name":"Paper 1","duration":"2 hours","marks":"100 marks","weight":"50%"},{"name":"Paper 2","duration":"2 hours","marks":"100 marks","weight":"50%"}]', 'blue', 0, 1, 6, 'Edexcel International GCSE Maths Tutor Online (4MA1)', 'Online tutoring for Pearson Edexcel International GCSE Mathematics 4MA1, Foundation & Higher. Book a free demo session.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_07', 'cambridge-lower-secondary-mathematics', 'Cambridge Lower Secondary Mathematics', 'Lower Secondary', NULL, 'Cambridge (CAIE)', 'Lower Secondary', 'Year 7 – 9', 'Strong foundations before IGCSE and O Level.', 'Building confident, curious mathematicians in Years 7 to 9, aligned with the Cambridge Lower Secondary framework and Checkpoint.', 'Lower Secondary is where key ideas in algebra, geometry and data are formed. We make those foundations solid with clear explanations, visual learning on a live whiteboard, and plenty of guided practice, so that the step up to IGCSE or O Level feels natural.', '["Number","Algebra","Geometry and measure","Statistics and probability","Thinking and working mathematically"]', '["Checkpoint preparation","Visual, interactive lessons","Homework & doubt support","Smooth path to IGCSE / O Level"]', NULL, 'teal', 0, 1, 7, 'Cambridge Lower Secondary Maths Tutor (Year 7–9)', 'Online maths tutoring for Cambridge Lower Secondary (Year 7–9) and Checkpoint. Build strong foundations. Free demo class.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO curricula (id, slug, title, short_title, code, board, level, year_range, tagline, summary, description, topics, highlights, exam_structure, accent, featured, published, sort_order, seo_title, seo_description, created_at, updated_at) VALUES ('cur_08', 'cambridge-primary-mathematics', 'Cambridge Primary Mathematics', 'Primary Maths', NULL, 'Cambridge (CAIE) / British Curriculum', 'Primary', 'Year 4 – 6', 'Make maths fun, visual and confidence-building.', 'Friendly, engaging online maths lessons for Years 4 to 6, following the Cambridge Primary and British curriculum.', 'Young learners thrive when maths makes sense. We use visual models, games and interactive whiteboard activities to build number sense, fluency and problem-solving, with regular updates for parents.', '["Number and place value","Calculation","Fractions, decimals and percentages","Geometry and measure","Statistics and probability"]', '["Fun, visual learning","Times tables & fluency","Problem-solving skills","Regular parent updates"]', NULL, 'orange', 0, 1, 8, 'Cambridge Primary Maths Tutor Online (Year 4–6)', 'Engaging one-to-one online maths tutoring for Cambridge Primary and British curriculum, Year 4–6. Free demo class.', '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO services (id, title, description, icon, sort_order, published, created_at, updated_at) VALUES ('svc_1', 'One-to-One Online Tutoring', 'Personalised attention for better progress. Every lesson is planned around one student.', 'UserRound', 1, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
