INSERT OR IGNORE INTO services (id, title, description, icon, sort_order, published, created_at, updated_at) VALUES ('svc_3', 'Past Papers & Exam Support', 'Build skills and boost confidence with targeted, timed past-paper practice.', 'FileCheck2', 3, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO services (id, title, description, icon, sort_order, published, created_at, updated_at) VALUES ('svc_4', 'Flexible Timings Worldwide', 'Learn at a time that suits your schedule, in your own time zone.', 'Clock', 4, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO services (id, title, description, icon, sort_order, published, created_at, updated_at) VALUES ('svc_5', 'Progress Updates & Reports', 'Track improvement and celebrate success with regular reports for parents.', 'TrendingUp', 5, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO services (id, title, description, icon, sort_order, published, created_at, updated_at) VALUES ('svc_6', 'Homework & Doubt Support', 'Guidance whenever your child needs it, so no question stays unanswered.', 'MessageCircleQuestion', 6, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO services (id, title, description, icon, sort_order, published, created_at, updated_at) VALUES ('svc_7', 'Concept Building & Problem Solving', 'Go beyond memorisation. Understand maths for life, then apply it.', 'Brain', 7, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO services (id, title, description, icon, sort_order, published, created_at, updated_at) VALUES ('svc_8', 'Worksheets, Quizzes & Assessments', 'Topical worksheets and quizzes to practise, check and close every gap.', 'ClipboardList', 8, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_1', 'Do you offer a free demo class?', 'Yes. Your first demo session is completely free with no obligation. Book it using the form on our Contact page or message us on WhatsApp at +92 349 5047810.', 'Getting started', 1, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_2', 'Which O Level Mathematics syllabus do you teach?', 'We specialise in Cambridge O Level Mathematics (4024), covering every syllabus topic plus exam technique for both Paper 1 (non-calculator) and Paper 2 (calculator), with extensive past-paper practice.', 'O Level', 2, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_3', 'Which other curricula and exam boards do you cover?', 'Cambridge IGCSE 0580, Additional Mathematics 0606, International Mathematics 0607, GCSE (Edexcel, AQA, OCR), Edexcel International GCSE, Cambridge Primary and Lower Secondary, and the British curriculum, from Year 4 to Year 11 and beyond.', 'Curricula', 3, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_4', 'How do online lessons work?', 'Lessons are live and one-to-one over video, using an interactive whiteboard so we can solve problems together. All you need is a laptop or tablet and a stable internet connection.', 'Lessons', 4, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_5', 'Do you teach students outside Pakistan?', 'Yes. We are based in Islamabad, Pakistan and teach students worldwide, including the UK, Middle East, Europe and beyond. Lessons are scheduled in your own time zone.', 'Lessons', 5, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_6', 'How will I know my child is improving?', 'We share regular progress updates and reports covering topics completed, test and past-paper scores, strengths, and the next areas to focus on.', 'Progress', 6, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_7', 'Can you help with homework and doubts between lessons?', 'Yes. Homework and doubt support is part of our service, so students can get guidance when they are stuck.', 'Lessons', 7, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO faqs (id, question, answer, category, sort_order, published, created_at, updated_at) VALUES ('faq_8', 'How long is each session and how often should we book?', 'Most students take 1-hour sessions two or three times a week. Exam-year students often add extra past-paper sessions closer to the exams. We will recommend a plan after the free demo.', 'Getting started', 8, 1, '2026-11-25T00:00:00.000Z', '2026-11-25T00:00:00.000Z');
