INSERT OR IGNORE INTO site_settings (key, value, updated_at) VALUES ('oLevelIntro', 'Struggling with O-Level Maths? Let''s make it easier. Our O Level Mathematics (4024) programme turns tricky topics into clear, step-by-step understanding, then builds exam confidence with past papers and proven strategies.', '2026-11-25T00:00:00.000Z');
INSERT OR IGNORE INTO site_settings (key, value, updated_at) VALUES ('aboutText', 'MathWhiz World Academy is an online maths academy based in Islamabad, Pakistan, helping students around the world understand, practise, apply and succeed in mathematics. We believe every student can succeed when concepts are explained clearly and practice is purposeful.

We specialise in Cambridge O Level Mathematics and support IGCSE, GCSE, Edexcel, AQA, and Cambridge Primary and Lower Secondary learners. Every lesson is one-to-one, interactive and tailored to the student''s goals.', '2026-11-25T00:00:00.000Z');
